// Dados desta sessão — vêm do trigger original do webhook
const triggerRaw = $('Webhook — onboarding.submetido').first().json;
const triggerBody = triggerRaw.body || triggerRaw;
const p = triggerBody.payload || triggerBody;
const clienteId = p.clienteId || '';
const nomeCliente = p.nomeCliente || 'a cliente';

// Perfil completo da cliente — vem do GET /api/v1/clientes/{id}
const perfil = $json.data || {};
const fichaAnterior = perfil.fichaClinica || null;

const linhasHoje = [
  p.estadoEmocional ? `Estado emocional: ${p.estadoEmocional}` : null,
  p.zonasTensao ? `Zonas de tensão: ${p.zonasTensao}` : null,
  p.condicoesAlergias ? `Condições/alergias: ${p.condicoesAlergias}` : null,
  p.objetivo ? `Foco desta sessão: ${p.objetivo}` : null,
  p.servico ? `Serviço: ${p.servico}` : null,
].filter(Boolean);
const dadosHoje = linhasHoje.length ? linhasHoje.join('\n') : 'Sem dados específicos.';
const contexto = fichaAnterior ? `FICHA ANTERIOR:\n${fichaAnterior}` : 'Primeira sessão.';

let idade = null;
if (perfil.dataNascimento) {
  const nasc = new Date(perfil.dataNascimento);
  if (!isNaN(nasc.getTime())) {
    const hoje = new Date();
    idade = hoje.getFullYear() - nasc.getFullYear();
    const aindaNaoFezAnos = (hoje.getMonth() < nasc.getMonth()) || (hoje.getMonth() === nasc.getMonth() && hoje.getDate() < nasc.getDate());
    if (aindaNaoFezAnos) idade--;
  }
}

const observacoesTxt = (perfil.observacoes || []).slice(0, 5).map(o => `- ${o.texto}`).join('\n');
const tarefasAbertas = (perfil.tarefas || []).filter(t => t.estado !== 'concluida' && t.estado !== 'cancelada').slice(0, 5).map(t => `- ${t.titulo}${t.descricao ? ': ' + t.descricao : ''}`).join('\n');
const mensagensTxt = (perfil.mensagens || []).slice(0, 3).map(m => `- [${m.estado}] ${(m.mensagemFinal || m.mensagemGerada || '').slice(0, 150)}`).join('\n');

const perfilLinhas = [
  idade !== null && idade >= 0 && idade < 120 ? `Idade: ${idade} anos` : null,
  perfil.totalSessoes ? `Total de sessões já realizadas: ${perfil.totalSessoes}` : 'Primeira sessão na Essence Wellness',
  perfil.historicoCondicoesAlergias ? `Condições/alergias permanentes registadas: ${perfil.historicoCondicoesAlergias}` : null,
  observacoesTxt ? `Notas internas da equipa:\n${observacoesTxt}` : null,
  tarefasAbertas ? `Tarefas/follow-ups em aberto:\n${tarefasAbertas}` : null,
  mensagensTxt ? `Mensagens recentes da equipa:\n${mensagensTxt}` : null,
].filter(Boolean);
const perfilTexto = perfilLinhas.length ? `PERFIL DA CLIENTE:\n${perfilLinhas.join('\n')}\n\n` : '';

const promptText = `És um sistema de apoio a uma terapeuta de bem-estar num centro de massagens em Portugal.\n\nCompila a ficha de referência da cliente ${nomeCliente} com os dados que ela própria reportou e o que a equipa já sabe sobre ela.\n\nDADOS REPORTADOS NESTA SESSÃO (a mais recente):\n${dadosHoje}\n\n${perfilTexto}${contexto}\n\nINSTRUÇÕES PARA A FICHA (parte factual):\n- Regista apenas o que foi reportado ou observado — sem diagnósticos\n- Sê conciso e direto: só a informação mais importante (saúde/segurança, foco da sessão, o que mudou) — usa o contexto extra (notas, tarefas, histórico) só se for relevante para esta sessão, não precisas de mencionar tudo\n- A SESSÃO DE HOJE é a prioridade e ocupa a maior parte do texto\n- Se há ficha anterior, termina esta parte com uma frase curta a chamar a atenção para o que foi feito ou reportado na sessão anterior, só como contexto\n- Máximo 2 parágrafos curtos, texto corrido, tom neutro e factual\n- Não repitas a mesma informação duas vezes\n- Não menciones aromas ou óleos essenciais — a escolha do aroma é sempre feita pela terapeuta no dia, não é uma preferência a registar\n\nINSTRUÇÕES PARA A RECOMENDAÇÃO (parágrafo final):\n- Começa com "Recomendação:"\n- Nunca diagnostiques nem uses linguagem médica — não és médica, és um apoio à terapeuta de bem-estar\n- Se a cliente estiver grávida, refere sempre o trimestre: no 1º trimestre pede cautela redobrada (evitar zona abdominal, confirmar autorização médica); no 2º/3º trimestre evitar pressão profunda nas pernas e estar atenta a sinais de pré-eclâmpsia ou inchaço súbito\n- Se houver alguma condição a confirmar (red flags) ou tarefa em aberto relevante para esta sessão, relembra a terapeuta\n- Sugere zonas a priorizar ou evitar e intensidade de pressão, com base nas zonas de tensão e condições reportadas\n- Não sugiras aromas nem óleos essenciais — isso é sempre decidido pela terapeuta no momento\n- Termina sempre com uma frase a lembrar que a decisão final da sessão é sempre da terapeuta\n- Máximo 1 parágrafo curto\n\nPortuguês europeu, tom neutro e profissional, máximo 3 parágrafos no total.`;

return [{ json: { clienteId, promptText } }];

const fichaClinica = $json?.choices?.[0]?.message?.content || '';
const clienteId = $('Preparar Prompt').all()[0]?.json?.clienteId || '';
return [{ json: { clienteId, fichaClinica } }];
